// 参数化基线：复数乘法 4 乘法器（16 位，free）
module top (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire signed [15:0] a,
    input  wire signed [15:0] b,
    input  wire signed [15:0] c,
    input  wire signed [15:0] d,
    output reg                out_valid,
    input  wire               out_ready,
    output reg  signed [32:0] y_re,
    output reg  signed [32:0] y_im
);
    // EVOLVE-BLOCK-START
    // Karatsuba/Gauss complex multiply: only 3 multipliers instead of 4.
    //   y_re = ac - bd
    //   y_im = (a+b)(c+d) - ac - bd   (since ad+bc = (a+b)(c+d) - ac - bd)
    assign in_ready = !out_valid || out_ready;

    wire signed [16:0] asum = a + b;
    wire signed [16:0] csum = c + d;
    wire signed [32:0] ac   = a * c;
    wire signed [32:0] bd   = b * d;
    wire signed [34:0] abcd = asum * csum;
    wire signed [34:0] im   = abcd - ac - bd;

    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0; y_re <= 0; y_im <= 0;
        end else begin
            if (out_valid && out_ready) out_valid <= 1'b0;
            if (in_valid && in_ready) begin
                y_re <= ac - bd;
                y_im <= im;
                out_valid <= 1'b1;
            end
        end
    end
    // EVOLVE-BLOCK-END
endmodule

